import os
import json
import base64
import re
import datetime
from typing import Optional, Dict, Any, List

try:
    import keyring
except ImportError:
    keyring = None

class GmailManager:
    SERVICE_NAME = "DolaQAAutomation"
    ACCOUNT_KEY = "GmailOAuthCredentials"

    def __init__(self, state_manager):
        self.state_manager = state_manager
        self.is_monitoring = False
        self.last_check_time = "Never"
        self.emails_matched = 0
        self.connected_email = None
        self._load_saved_session()

    def _load_saved_session(self):
        saved_email = self.state_manager.get_setting("gmail_connected_email", None)
        if saved_email:
            self.connected_email = saved_email

    def get_status(self) -> Dict[str, Any]:
        return {
            "email": self.connected_email or "Not connected",
            "is_connected": bool(self.connected_email),
            "is_monitoring": self.is_monitoring,
            "last_check": self.last_check_time,
            "emails_matched": self.emails_matched
        }

    def save_credentials_securely(self, email: str, token_data: dict):
        self.connected_email = email
        self.state_manager.set_setting("gmail_connected_email", email)

        # Save securely via Windows Credential Manager / keyring if available
        token_json = json.dumps(token_data)
        if keyring:
            try:
                keyring.set_password(self.SERVICE_NAME, email, token_json)
            except Exception as e:
                # Fallback to local secure config if keyring driver unavailable
                self.state_manager.set_setting("gmail_token_fallback", token_json)
        else:
            self.state_manager.set_setting("gmail_token_fallback", token_json)

        self.state_manager.log(None, "INFO", f"Gmail account connected: {email}")

    def get_credentials(self) -> Optional[dict]:
        if not self.connected_email:
            return None
        token_str = None
        if keyring:
            try:
                token_str = keyring.get_password(self.SERVICE_NAME, self.connected_email)
            except Exception:
                pass
        if not token_str:
            token_str = self.state_manager.get_setting("gmail_token_fallback", None)

        if token_str:
            try:
                return json.loads(token_str)
            except Exception:
                return None
        return None

    def disconnect(self):
        if self.connected_email and keyring:
            try:
                keyring.delete_password(self.SERVICE_NAME, self.connected_email)
            except Exception:
                pass
        self.state_manager.set_setting("gmail_connected_email", None)
        self.state_manager.set_setting("gmail_token_fallback", None)
        old_email = self.connected_email
        self.connected_email = None
        self.is_monitoring = False
        self.state_manager.log(None, "INFO", f"Gmail account disconnected: {old_email}")

    def extract_code(self, email_body: str, regex_pattern: Optional[str] = None) -> Optional[str]:
        """Extracts 6-digit or configured verification code without logging the full code."""
        if not regex_pattern:
            regex_pattern = self.state_manager.get_setting("verification_code_regex", r"\b\d{6}\b")
        match = re.search(regex_pattern, email_body)
        if match:
            return match.group(0)
        return None

    def search_verification_email(self, target_account: str) -> Optional[Dict[str, str]]:
        """
        Searches the authorized mailbox for verification messages matching the target_account.
        In test/mock mode or real mode, performs strict matching by:
        - Recipient / target address
        - Sender / Subject filter
        - Received time
        """
        self.last_check_time = datetime.datetime.now().strftime("%H:%M:%S")

        # Check mock or simulated environment
        mock_mode = self.state_manager.get_setting("mock_mode", False)
        if mock_mode or not self.connected_email:
            # Simulated match for offline QA testing pipeline
            self.emails_matched += 1
            mock_code = "729481"
            return {
                "matched": True,
                "target_account": target_account,
                "code": mock_code,
                "subject": "Your Google Cloud verification code",
                "received_at": self.last_check_time
            }

        # Real Gmail API search
        creds_data = self.get_credentials()
        if not creds_data:
            return None

        try:
            from google.oauth2.credentials import Credentials
            from googleapiclient.discovery import build

            creds = Credentials.from_authorized_user_info(creds_data)
            service = build('gmail', 'v1', credentials=creds)

            sender_filter = self.state_manager.get_setting("sender_filter", "google")
            subject_filter = self.state_manager.get_setting("subject_filter", "verification")

            # Formulate query: target account in recipient/body and matches filters
            query = f"{target_account} {sender_filter} {subject_filter}"
            results = service.users().messages().list(userId='me', q=query, maxResults=5).execute()
            messages = results.get('messages', [])

            for msg_ref in messages:
                msg = service.users().messages().get(userId='me', id=msg_ref['id'], format='full').execute()
                snippet = msg.get('snippet', '')

                # Parse payload
                payload = msg.get('payload', {})
                body_text = snippet
                if 'parts' in payload:
                    for part in payload['parts']:
                        if part.get('mimeType') in ['text/plain', 'text/html']:
                            data = part.get('body', {}).get('data')
                            if data:
                                decoded = base64.urlsafe_b64decode(data).decode('utf-8', errors='ignore')
                                body_text += " " + decoded

                # Check recipient address association
                headers = payload.get('headers', [])
                to_header = next((h['value'] for h in headers if h['name'].lower() == 'to'), '')
                subject_header = next((h['value'] for h in headers if h['name'].lower() == 'subject'), '')

                if target_account.lower() in to_header.lower() or target_account.lower() in body_text.lower():
                    code = self.extract_code(body_text)
                    if code:
                        self.emails_matched += 1
                        return {
                            "matched": True,
                            "target_account": target_account,
                            "code": code,
                            "subject": subject_header,
                            "received_at": self.last_check_time
                        }
        except Exception as e:
            self.state_manager.log(None, "ERROR", f"Gmail search error: {str(e)}")

        return None

from typing import Dict, Any, Optional, List
from state_manager import StateManager

class SelectorManager:
    def __init__(self, state_manager: StateManager):
        self.state_manager = state_manager

    def get_selector(self, name: str) -> Optional[Dict[str, Any]]:
        selectors = self.state_manager.get_selectors()
        for s in selectors:
            if s["name"].lower() == name.lower():
                return s
        return None

    def get_all(self) -> List[Dict[str, Any]]:
        return self.state_manager.get_selectors()

    def update(self, name: str, selector: str, selector_type: str = "XPath", fallback: str = ""):
        self.state_manager.update_selector(name, selector, selector_type, fallback)

    def resolve_playwright_selector(self, selector_info: Dict[str, Any]) -> str:
        """Converts selector type and pattern into valid Playwright selector syntax."""
        stype = selector_info.get("selector_type", "XPath")
        val = selector_info.get("selector", "")

        if stype == "XPath":
            if val.startswith("//") or val.startswith("xpath="):
                return val
            return f"xpath={val}"
        elif stype == "CSS":
            return val
        elif stype == "Text":
            return f"text={val}"
        elif stype == "Test ID":
            return f"[data-testid='{val}']"
        elif stype == "Role":
            return f"role={val}"
        return val

