class SelectorDialog(QDialog):
    def __init__(self, worker: QAWorker, parent=None):
        super().__init__(parent)
        self.worker = worker
        self.setWindowTitle(f"Selector Required — Worker #{worker.worker_id}")
        self.setMinimumWidth(520)
        layout = QVBoxLayout(self)

        info = worker.pending_selector or {}
        layout.addWidget(QLabel(f"<b>Worker:</b> #{worker.worker_id}"))
        layout.addWidget(QLabel(f"<b>Step:</b> {info.get('step', '?')}"))
        layout.addWidget(QLabel(f"<b>URL:</b> {info.get('url', '?')}"))
        layout.addWidget(QLabel("<b>Tried selectors:</b>"))
        for s in info.get("tried", []):
            layout.addWidget(QLabel(f"  • {s}"))

        layout.addWidget(QLabel("<b>XPath / CSS selector:</b>"))
        self.sel_edit = QLineEdit()
        self.sel_edit.setPlaceholderText("//input[@name='...']  or  .css-class")
        layout.addWidget(self.sel_edit)

        self.sel_type = QComboBox()
        self.sel_type.addItems(["XPath", "CSS", "Text", "Test ID", "Role"])
        layout.addWidget(self.sel_type)

        btns = QDialogButtonBox(QDialogButtonBox.Ok | QDialogButtonBox.Cancel)
        btns.accepted.connect(self._on_save)
        btns.rejected.connect(self.reject)
        layout.addWidget(btns)

    def _on_save(self):
        sel = self.sel_edit.text().strip()
        if not sel:
            return
        step = (self.worker.pending_selector or {}).get("step", "")
        # Update the selector in the DB
        self.worker.state_manager.update_selector(step, sel, self.sel_type.currentText())
        self.worker.pending_selector = None
        self.worker._selector_event.set()   # unblock the worker thread
        self.accept()


